function hx(h){var n=parseInt(h.replace("#",""),16);return[(n>>16)&255,(n>>8)&255,n&255]}
function rh(r,g,b){return"#"+[r,g,b].map(function(x){return Math.round(Math.max(0,Math.min(255,x))).toString(16).padStart(2,"0")}).join("")}
function dk(h,a){var c=hx(h);return rh(c[0]*(1-a),c[1]*(1-a),c[2]*(1-a))}
function lt(h,a){var c=hx(h);return rh(c[0]+(255-c[0])*a,c[1]+(255-c[1])*a,c[2]+(255-c[2])*a)}
function isLt(h){var c=hx(h);return(c[0]*299+c[1]*587+c[2]*114)/1000>150}

function ShirtPreview(props){
  var color=props.color,img=props.img,sc=props.sc,dy=props.dy,dx=props.dx,big=props.big,photo=props.photo;
  if(photo){
    return <div style={{position:"relative",width:"100%",maxWidth:big?310:270,margin:"0 auto"}}>
      <img src={photo} alt="shirt" style={{width:"100%",borderRadius:8,display:"block"}}/>
      {img&&<img src={img} alt="design" style={{position:"absolute",left:dx+"%",top:dy+"%",width:(sc*30)+"%",transform:"translateX(-50%)",opacity:0.92,pointerEvents:"none"}}/>}
      {!img&&<div style={{position:"absolute",left:"50%",top:"35%",transform:"translateX(-50%)",border:"2px dashed rgba(255,255,255,0.3)",borderRadius:6,padding:"20px 30px",color:"rgba(255,255,255,0.4)",fontSize:12,textAlign:"center"}}>Your Design</div>}
    </div>;
  }
  var W=big?400:360,cx=W/2,sm=isLt(color)?"rgba(0,0,0,0.06)":"rgba(255,255,255,0.04)";
  var d1=dk(color,0.1),l1=lt(color,0.08),d2=dk(color,0.18),hi=lt(color,0.12);
  var uid="sh"+color.replace("#","")+(big?"B":"S");
  var body="M 80,380 C 78,340 76,280 80,210 C 81,195 79,186 68,178 L 30,168 C 18,164 8,148 10,130 C 12,112 24,94 38,78 C 48,66 60,54 72,42 L 76,38 C 84,22 104,10 128,5 C 146,1 166,0 "+cx+",0 C 214,0 234,1 252,5 C 276,10 296,22 304,38 L 308,42 C 320,54 332,66 342,78 C 356,94 368,112 370,130 C 372,148 362,164 350,168 L 312,178 C 301,186 299,195 300,210 C 304,280 302,340 300,380 Z";
  if(big){body="M 85,400 C 83,355 80,290 84,215 C 85,198 83,188 72,180 L 30,170 C 16,166 5,148 7,128 C 9,108 22,88 38,72 C 50,58 64,44 78,32 L 82,28 C 92,12 114,2 140,0 C 160,0 180,0 "+cx+",0 C 220,0 240,0 260,0 C 286,2 308,12 318,28 L 322,32 C 336,44 350,58 362,72 C 378,88 391,108 393,128 C 395,148 384,166 370,170 L 328,180 C 317,188 315,198 316,215 C 320,290 317,355 315,400 Z"}
  return(
    <svg viewBox={"0 0 "+W+" "+(big?420:400)} style={{width:"100%",maxWidth:big?310:270,display:"block",margin:"0 auto",filter:"drop-shadow(0 5px 14px rgba(0,0,0,0.1))"}}>
      <defs>
        <linearGradient id={"gA"+uid} x1="0.15" y1="0" x2="0.85" y2="1"><stop offset="0%" stopColor={l1} stopOpacity="0.2"/><stop offset="40%" stopColor={color} stopOpacity="0"/><stop offset="70%" stopColor={d1} stopOpacity="0.15"/><stop offset="100%" stopColor={d2} stopOpacity="0.2"/></linearGradient>
        <radialGradient id={"gB"+uid} cx="0.48" cy="0.28" r="0.35"><stop offset="0%" stopColor={hi} stopOpacity="0.08"/><stop offset="100%" stopColor="transparent"/></radialGradient>
        <clipPath id={"cp"+uid}><path d={body}/></clipPath>
      </defs>
      <path d={body} fill={color}/><path d={body} fill={"url(#gA"+uid+")"}/><path d={body} fill={"url(#gB"+uid+")"}/>
      <path d={"M "+(cx-28)+",4 Q "+(cx-8)+",28 "+cx+",32 Q "+(cx+8)+",28 "+(cx+28)+",4"} fill="none" stroke={sm} strokeWidth="2.5"/>
      <line x1={cx} y1={38} x2={cx} y2={(big?392:372)} stroke={isLt(color)?"rgba(0,0,0,0.015)":"rgba(0,0,0,0.06)"} strokeWidth="0.5"/>
      <line x1={80} y1={(big?400:380)} x2={(big?315:300)} y2={(big?400:380)} stroke={sm} strokeWidth="1.5"/>
      {img?<g clipPath={"url(#cp"+uid+")"}><image href={img} x={dx-(sc*90)/2} y={dy} width={sc*90} height={sc*90} preserveAspectRatio="xMidYMid meet" opacity="0.92"/></g>:
      <g opacity="0.1"><rect x={cx-36} y={80} width={72} height={72} rx="4" fill="none" stroke={isLt(color)?"#555":"#fff"} strokeWidth="1.5" strokeDasharray="5 3"/><text x={cx} y={120} textAnchor="middle" fill={isLt(color)?"#555":"#fff"} fontSize="10" fontFamily="Georgia,serif">Your Design</text></g>}
    </svg>
  );
}

